import type { PermissionResolver } from './rbac';

export interface AccessSubject {
  userId: string;
  tenantId: string;
  roles: string[];
}

export interface AccessResource {
  id: string;
  tenantId: string;
  /** 谁拥有这份资源 */
  ownerId: string;
  /** 资源分级，比如 public / internal / secret */
  classification?: string;
}

export interface AccessRequest {
  subject: AccessSubject;
  /** 比如 doc:read */
  action: string;
  resource: AccessResource;
  /** 请求发生的时刻。时间是请求的一部分，不要在引擎里读时钟。 */
  atMs: number;
}

export interface PolicyCondition {
  /** 资源必须和请求者同租户 */
  sameTenant?: boolean;
  /** 资源属主必须是请求者本人 */
  ownerOnly?: boolean;
  /** 请求者至少带着其中一个角色 */
  roles?: string[];
  /** 资源分级必须在这个集合里 */
  classification?: string[];
  /** 只在这个时间窗内生效，左闭右开 */
  between?: { fromMs: number; toMs: number };
}

export interface Policy {
  id: string;
  effect: 'allow' | 'deny';
  /** 这条规则管哪些动作，支持 doc:* 这样的通配 */
  actions: string[];
  /** 不写就是「无条件」 */
  condition?: PolicyCondition;
}

export interface PolicyDecision {
  allowed: boolean;
  /** policy:<id> / rbac-denied / default-deny */
  reason: string;
}

export interface PolicyEngine {
  evaluate(request: AccessRequest): PolicyDecision;
}

export function createPolicyEngine(rbac: PermissionResolver, policies: Policy[]): PolicyEngine {
  // TODO: 在这里实现
  throw new Error('not implemented');
}

