                exp: issuedAt + options.ttlMs,
            };
            // 纪元是可选的：第 4 关之前没人会传
            if (typeof input.epoch === 'number')
                claims.epoch = input.epoch;
            const payload = encodeSegment(claims);
            return payload + SEPARATOR + sign(payload);
        },
        verify(token) {
            if (typeof token !== 'string')
                return null;
            const parts = token.split(SEPARATOR);
            if (parts.length !== SEGMENTS)
                return null;
            // 验签是入口：下面这行之前，payload 只是一串攻击者可以随便写的字符
            if (!constantTimeEqual(sign(parts[0]), parts[1]))
                return null;
            const claims = decodeSegment(parts[0]);
            if (!claims || typeof claims.exp !== 'number')
                return null;
            // 到点即失效：exp 是「最后一刻的下一刻」
            if (now() >= claims.exp)
                return null;
            return claims;
        },
    };
}

