// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface RefreshOptions {
//   ttlMs: number;
// }
//
// export interface TokenPair {
//   accessToken: string;
//   refreshToken: string;
// }
//
// export interface RefreshService {
//   start(input: { userId: string; tenantId: string }): TokenPair;
//   rotate(refreshToken: string): TokenPair | null;
// }
//
// interface RefreshRecord {
//   family: string;
//   sub: string;
//   tenantId: string;
//   exp: number;
//   /** 用过了就标记，但不删 —— 删了就发现不了重放 */
//   used: boolean;
// }

import { COLLECTIONS } from './contract';
import { randomId, sha256 } from './support/crypto';
import { now } from '@lab/env';
export function createRefreshService(store, issuer, options) {
    function read(token) {
        const raw = store.get(COLLECTIONS.refresh, sha256(token));
        return raw ? raw : null;
    }
    function mint(family, sub, tenantId) {
        const refreshToken = randomId('rt');
        const record = { family, sub, tenantId, exp: now() + options.ttlMs, used: false };
        store.put(COLLECTIONS.refresh, sha256(refreshToken), record);
        return { accessToken: issuer.issue({ userId: sub, tenantId, sid: family }), refreshToken };
    }
    /** 重放告警：这条链上的所有令牌一起作废，包括还没用过的那张 */
    function revokeFamily(family) {
        for (const key of store.keys(COLLECTIONS.refresh)) {
            const record = store.get(COLLECTIONS.refresh, key);
            if (record && record.family === family)
                store.remove(COLLECTIONS.refresh, key);
        }
    }
    return {
        start(input) {
            // 族 id 同时就是会话 id：一次登录 = 一条链
            return mint(randomId('sid'), input.userId, input.tenantId);
        },
        rotate(refreshToken) {
            const record = read(refreshToken);
            if (!record)
                return null;
            if (record.used) {
                // 同一张出现了第二次 —— 它被复制过，两边都不能再信
                revokeFamily(record.family);
                return null;
            }
            if (now() >= record.exp) {
                store.remove(COLLECTIONS.refresh, sha256(refreshToken));
                return null;
            }
            const used = { ...record, used: true };
            store.put(COLLECTIONS.refresh, sha256(refreshToken), used);
            return mint(record.family, record.sub, record.tenantId);
        },
    };
}

