//   clientId: string;
//   redirectUri: string;
//   challenge: string;
//   userId: string;
//   tenantId: string;
//   exp: number;
//   used: boolean;
// }

import { COLLECTIONS } from './contract';
import { constantTimeEqual, randomId, sha256 } from './support/crypto';
import { now } from '@lab/env';
/** 唯一接受的挑战算法。plain 是历史包袱，不给它留门。 */
const S256 = 'S256';
export function createOAuthServer(store, refresh, options) {
    function registrationOf(clientId) {
        return options.clients.filter((client) => client.clientId === clientId)[0];
    }
    function save(code, record) {
        store.put(COLLECTIONS.codes, sha256(code), record);
    }
    return {
        authorize(request) {
            const client = registrationOf(request.clientId);
            if (!client)
                return null;
            if (client.redirectUris.indexOf(request.redirectUri) < 0)
                return null;
            if (request.codeChallengeMethod !== S256 || !request.codeChallenge)
                return null;
            const code = randomId('code');
            save(code, {
                clientId: request.clientId,
                redirectUri: request.redirectUri,
                challenge: request.codeChallenge,
                userId: request.userId,
                tenantId: request.tenantId,
                exp: now() + options.ttlMs,
                used: false,
            });
            return code;
        },
        exchange(request) {
            const key = sha256(request.code || '');
            const record = store.get(COLLECTIONS.codes, key);
            if (!record || record.used)
                return null;
            // 先烧掉再检查：攻击者截到码之后只有这一次机会去猜 verifier
            save(request.code, { ...record, used: true });
            if (now() >= record.exp)
                return null;
            if (record.clientId !== request.clientId)
                return null;
            if (record.redirectUri !== request.redirectUri)
                return null;
            if (!constantTimeEqual(sha256(request.codeVerifier || ''), record.challenge))
                return null;
            // 所有登录路径最终都汇到同一处发令牌
            return refresh.start({ userId: record.userId, tenantId: record.tenantId });
        },
    };
}

