// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface PermissionResolver {
//   permissionsOf(roles: string[]): string[];
//   can(roles: string[], permission: string): boolean;
// }

const ANY = '*';
const WILDCARD_SUFFIX = ':*';
/** 授予的 pattern 能不能覆盖被问的 permission。方向是单向的。 */
function grants(pattern, permission) {
    if (pattern === ANY)
        return true;
    if (pattern === permission)
        return true;
    if (pattern.slice(-WILDCARD_SUFFIX.length) !== WILDCARD_SUFFIX)
        return false;
    // 只在段边界上生效：doc:* 覆盖 doc:read，但不覆盖 document:read
    return permission.indexOf(pattern.slice(0, pattern.length - 1)) === 0;
}
export function createRbac(directory) {
    /**
     * 角色定义的缓存，跨查询存活。
     * 缓存的是**定义**而不是展开后的权限：定义是事实，展开结果依赖于问法。
     */
    const definitions = new Map();
    function definitionOf(name) {
        if (!definitions.has(name))
            definitions.set(name, directory.read(name));
        return definitions.get(name);
    }
    function expand(roles) {
        const queue = roles.slice();
        const seen = new Set();
        const collected = new Set();
        while (queue.length > 0) {
            const name = queue.shift();
            // 环在这里终止：一轮查询里同一个角色只展开一次
            if (seen.has(name))
                continue;
            seen.add(name);
            const definition = definitionOf(name);
            if (!definition)
                continue;
            for (const permission of definition.permissions)
                collected.add(permission);
            for (const parent of definition.inherits)
                queue.push(parent);
        }
        return Array.from(collected).sort();
    }
    return {
        permissionsOf(roles) {
            return expand(roles);
        },
        can(roles, permission) {
            return expand(roles).some((pattern) => grants(pattern, permission));
        },
    };
}

