// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface AccessSubject {
//   userId: string;
//   tenantId: string;
//   roles: string[];
// }
//
// export interface AccessResource {
//   id: string;
//   tenantId: string;
//   ownerId: string;
//   classification?: string;
// }
//
// export interface AccessRequest {
//   subject: AccessSubject;
//   action: string;
//   resource: AccessResource;
//   atMs: number;
// }
//
// export interface PolicyCondition {
//   sameTenant?: boolean;
//   ownerOnly?: boolean;
//   roles?: string[];
//   classification?: string[];
//   between?: { fromMs: number; toMs: number };
// }
//
// export interface Policy {
//   id: string;
//   effect: 'allow' | 'deny';
//   actions: string[];
//   condition?: PolicyCondition;
// }
//
// export interface PolicyDecision {
//   allowed: boolean;
//   reason: string;
// }
//
// export interface PolicyEngine {
//   evaluate(request: AccessRequest): PolicyDecision;
// }

const ANY = '*';
const WILDCARD_SUFFIX = ':*';
/**
 * 动作匹配。规则和第 8 关的权限通配是同一条 —— 真实代码里
 * 这两处应该共用一个实现，这里各写一份是为了让每一关都能独立读懂。
 */
function covers(pattern, action) {
    if (pattern === ANY || pattern === action)
        return true;
    if (pattern.slice(-WILDCARD_SUFFIX.length) !== WILDCARD_SUFFIX)
        return false;
    return action.indexOf(pattern.slice(0, pattern.length - 1)) === 0;
}
function withinWindow(window, atMs) {
    return atMs >= window.fromMs && atMs < window.toMs;
}
/** 条件里每一项都是可选的：没写就等于不限制 */
function holds(condition, request) {
    if (!condition)
        return true;
    const subject = request.subject;
    const resource = request.resource;
    return [
        !condition.sameTenant || resource.tenantId === subject.tenantId,
        !condition.ownerOnly || resource.ownerId === subject.userId,
        !condition.roles || condition.roles.some((role) => subject.roles.indexOf(role) >= 0),
        !condition.classification ||
            condition.classification.indexOf(resource.classification || '') >= 0,
        !condition.between || withinWindow(condition.between, request.atMs),
    ].every(Boolean);
}
export function createPolicyEngine(rbac, policies) {
    function applicable(request) {
        return policies.filter((policy) => policy.actions.some((pattern) => covers(pattern, request.action)) &&
            holds(policy.condition, request));
    }
    function firstWith(matched, effect) {
        return matched.filter((policy) => policy.effect === effect)[0];
    }
    return {
        evaluate(request) {
            // 角色决定上限，策略只在上限之内挑
            if (!rbac.can(request.subject.roles, request.action)) {
                return { allowed: false, reason: 'rbac-denied' };
            }
            const matched = applicable(request);
            // deny 先看，而且不看顺序：只要有一条就够了
            const denied = firstWith(matched, 'deny');
            if (denied)
                return { allowed: false, reason: 'policy:' + denied.id };
            const allowed = firstWith(matched, 'allow');
            if (allowed)
                return { allowed: true, reason: 'policy:' + allowed.id };
            // 显式的最后一行：没匹配上就是不许
            return { allowed: false, reason: 'default-deny' };
        },
    };
}

