import { now } from '@lab/env';
const SEPARATOR = '|';
export function createPermissionCache(engine, options) {
    const entries = new Map();
    const counters = { hits: 0, misses: 0 };
    /** 决定取决于哪些东西，键里就得有哪些东西 —— 时间除外，它由 TTL 管 */
    function keyOf(request) {
        return [
            request.subject.tenantId,
            request.subject.userId,
            request.action,
            request.resource.id,
        ].join(SEPARATOR);
    }
    function dropWhere(matches) {
        for (const pair of Array.from(entries.entries())) {
            if (matches(pair[1]))
                entries.delete(pair[0]);
        }
    }
    return {
        evaluate(request) {
            const key = keyOf(request);
            const cached = entries.get(key);
            if (cached && now() < cached.expiresAt) {
                counters.hits += 1;
                return cached.decision;
            }
            counters.misses += 1;
            const decision = engine.evaluate(request);
            // 拒绝也缓存：被拒的流量往往比被放行的还密集
            entries.set(key, {
                decision,
                expiresAt: now() + options.ttlMs,
                userId: request.subject.userId,
                resourceId: request.resource.id,
            });
            return decision;
        },
        invalidateSubject(userId) {
            dropWhere((entry) => entry.userId === userId);
        },
        invalidateResource(resourceId) {
            dropWhere((entry) => entry.resourceId === resourceId);
        },
        invalidateAll() {
            entries.clear();
        },
        stats() {
            return { hits: counters.hits, misses: counters.misses };
        },
    };
}

