// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface AuditEvent {
//   actor: string;
//   tenantId: string;
//   action: string;
//   outcome: 'allow' | 'deny';
//   detail?: Record<string, unknown>;
