//
// export interface HardenedLogin {
//   login(input: { userId: string; password: string; tenantId: string }): Promise<LoginResult>;
// }
//
// interface LockState {
//   failures: number;
//   lockedUntil: number;
// }

import { COLLECTIONS } from './contract';
import { hmac } from './support/crypto';
import { now } from '@lab/env';
/** 链的起点。第一条的 prevHash 指向它。 */
const GENESIS = 'genesis';
const MASK = '[redacted]';
const KEY_WIDTH = 6;
/** 字段名里出现这些词就当作秘密 */
const SENSITIVE = ['password', 'secret', 'token', 'authorization', 'verifier', 'code'];
function isSensitive(key) {
    const lower = key.toLowerCase();
    return SENSITIVE.some((word) => lower.indexOf(word) >= 0);
}
function redactValue(value) {
    if (!value || typeof value !== 'object')
        return value;
    if (Array.isArray(value))
        return value.map(redactValue);
    return redact(value);
}
/** 递归脱敏：秘密经常藏在「整个请求体」这种嵌套结构里 */
function redact(detail) {
    const clean = {};
    for (const key of Object.keys(detail)) {
        clean[key] = isSensitive(key) ? MASK : redactValue(detail[key]);
    }
    return clean;
}
export function createAuditLog(store, options) {
    function bodyOf(entry) {
        return [
            entry.seq,
            entry.at,
            entry.actor,
            entry.tenantId,
            entry.action,
            entry.outcome,
            JSON.stringify(entry.detail),
            entry.prevHash,
        ].join('|');
    }
    /** 用 HMAC 而不是普通摘要：能改库的人不该能重算这个值 */
    function hashOf(entry) {
        return hmac(options.secret, bodyOf(entry));
    }
    function keyOf(seq) {
        return String(seq).padStart(KEY_WIDTH, '0');
    }
    function all() {
        const keys = store.keys(COLLECTIONS.audit).sort();
        const found = [];
        for (const key of keys) {
            const record = store.get(COLLECTIONS.audit, key);
            if (record)
                found.push(record);
        }
        return found;
    }
    return {
        record(event) {
            const existing = all();
            const previous = existing[existing.length - 1];
            const entry = {
                seq: previous ? previous.seq + 1 : 1,
                at: now(),
                actor: event.actor,
                tenantId: event.tenantId,
                action: event.action,
                outcome: event.outcome,
                detail: redact(event.detail || {}),
                prevHash: previous ? previous.hash : GENESIS,
                hash: '',
            };
            entry.hash = hashOf(entry);
            store.put(COLLECTIONS.audit, keyOf(entry.seq), entry);
            return entry;
        },
        entries() {
            return all();
        },
        verifyChain() {
            let expected = GENESIS;
            const list = all();
            for (let index = 0; index < list.length; index += 1) {
                const entry = list[index];
                // 三种断裂：编号跳了、接不上上一条、内容被改过
                if (entry.seq !== index + 1)
                    return index;
                if (entry.prevHash !== expected)
                    return index;
                if (entry.hash !== hashOf(entry))
                    return index;
                expected = entry.hash;
            }
            return -1;
        },
    };
}
export function createHardenedLogin(store, credentials, audit, options) {
    function stateOf(userId) {
        const record = store.get(COLLECTIONS.lockouts, userId);
        if (!record)
            return { failures: 0, lockedUntil: 0 };
        // 锁定期满就当作从头开始，不需要另外的清理任务
        if (record.lockedUntil && record.lockedUntil <= now())
            return { failures: 0, lockedUntil: 0 };
        return record;
    }
    function save(userId, state) {
        store.put(COLLECTIONS.lockouts, userId, state);
    }
    function trace(userId, tenantId, outcome, reason) {
        audit.record({ actor: userId, tenantId, action: 'auth:login', outcome, detail: { reason } });
    }
    return {
        async login(input) {
            const state = stateOf(input.userId);
            // 锁定判断在验密码之前：结果已经注定，那次慢哈希纯属白烧
            if (state.lockedUntil > now()) {
                trace(input.userId, input.tenantId, 'deny', 'locked');
                return { ok: false, reason: 'locked' };
            }
            const matched = await credentials.verify(input.userId, input.password);
            if (matched) {
                save(input.userId, { failures: 0, lockedUntil: 0 });
                trace(input.userId, input.tenantId, 'allow', 'ok');
                return { ok: true, reason: 'ok' };
            }
            const failures = state.failures + 1;
            const locked = failures >= options.maxAttempts;
            save(input.userId, { failures, lockedUntil: locked ? now() + options.lockoutMs : 0 });
            trace(input.userId, input.tenantId, 'deny', 'invalid-credentials');
            return { ok: false, reason: 'invalid-credentials' };
        },
    };
}

