}

export interface ReplicatedLog {
  /** 写 leader 并复制；等够 minInSync 个确认才 resolve */
  produce(key: string, value: string): Promise<number>;
  /** 只返回高水位以下的记录 */
  read(offset: number, max: number): StoredRecord[];
  /** 已提交的边界：这个位置本身还不可见 */
  highWatermark(): number;
  inSyncReplicas(): string[];
  /** leader 的末尾，可能高于高水位 */
  endOffset(): number;
}

