  /** 剔除超时成员并再平衡，返回移动了多少个分片 */
  tick(): number;
  /** 认领一批消息（正在处理） */
  claim(memberId: string, offsets: number[]): void;
  /** 处理完了，交还一条 */
  release(memberId: string, offset: number): void;
  /** 因为成员消失而回到队列的消息 */
  requeued(): number[];
  members(): string[];
  assignmentOf(memberId: string): number[];
}

