        async send(records) {
            await sleep(options.lagMs + extra);
            for (const record of records) {
                if (record.offset > acked)
                    acked = record.offset;
            }
        },
        ackedOffset() {
            return acked;
        },
        stall(extraMs) {
            extra = extraMs;
        },
        resume() {
            extra = 0;
        },
    };
}

