// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface AppendResult {
//   offset: number;
//   segmentId: number;
//   index: number;
// }
//
// export interface LogOptions {
//   segmentBytes: number;
// }
//
// export interface MessageLog {
//   append(key: string, value: string): AppendResult;
//   read(offset: number, max: number): StoredRecord[];
//   endOffset(): number;
//   segments(): SegmentInfo[];
//   flush(): Promise<void>;
// }

export function createLog(storage, options) {
    let nextOffset = 0;
    /** 活动段只需要这两个数 */
    let activeSegmentId = -1;
    let activeBytes = 0;
    function roll() {
        activeSegmentId = storage.createSegment(nextOffset);
        activeBytes = 0;
    }
    /** 判断在追加之前做：先追加再看超没超，每个段都会多出一条 */
    function segmentFor(size) {
        if (activeSegmentId < 0)
            roll();
        // 段是空的时候无条件接受：超大的单条记录也得有地方放
        else if (activeBytes > 0 && activeBytes + size > options.segmentBytes)
            roll();
        return activeSegmentId;
    }
    return {
        append(key, value) {
            const size = storage.sizeOf(key, value);
            const segmentId = segmentFor(size);
            const offset = nextOffset;
            const index = storage.append(segmentId, { offset, key, value });
            nextOffset += 1;
            activeBytes += size;
            return { offset, segmentId, index };
        },
        read(offset, max) {
            const found = [];
            if (max <= 0)
                return found;
            for (const segment of storage.segments()) {
                // 整段都在 offset 之前，一条都不用读
                if (offset >= segment.baseOffset + segment.count)
                    continue;
                for (let index = 0; index < segment.count; index += 1) {
                    // 数据来自设备：掉电丢掉的部分在这里自然读不到
                    const record = storage.readAt(segment.id, index);
                    if (!record)
                        break;
                    if (record.offset < offset)
                        continue;
                    found.push(record);
                    if (found.length >= max)
                        return found;
                }
            }
            return found;
        },
        endOffset() {
            return nextOffset;
        },
        segments() {
            return storage.segments();
        },
        async flush() {
            await storage.fsync();
        },
    };
}

