// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface ProducerOptions {
//   batchSize: number;
//   lingerMs: number;
// }
//
// export interface ProducerStats {
//   batches: number;
//   records: number;
// }
//
// export interface Producer {
//   send(key: string, value: string): Promise<number>;
//   flush(): Promise<void>;
//   buffered(): number;
//   stats(): ProducerStats;
// }
//
// interface Pending {
//   key: string;
//   value: string;
//   settle(offset: number): void;
// }

export function createProducer(log, options) {
    let buffer = [];
    let timer = null;
    /** 批与批之间靠这条链保持有序 */
    let chain = Promise.resolve();
    const counters = { batches: 0, records: 0 };
    function cancelTimer() {
        if (timer === null)
            return;
        clearTimeout(timer);
        timer = null;
    }
    function flushNow() {
        cancelTimer();
        // 先把缓冲整个换掉，再去做异步落盘：
        // 反过来的话，落盘期间新来的消息会掉进一个已经分发过 resolve 的批次里
        const batch = buffer;
        buffer = [];
        if (batch.length === 0)
            return chain;
        counters.batches += 1;
        counters.records += batch.length;
        chain = chain.then(async () => {
            const offsets = batch.map((entry) => log.append(entry.key, entry.value).offset);
            // 一整批只 fsync 一次，固定成本被摊薄
            await log.flush();
            batch.forEach((entry, index) => entry.settle(offsets[index]));
        });
        return chain;
    }
    return {
        send(key, value) {
            return new Promise((resolve) => {
                buffer.push({ key, value, settle: resolve });
                if (buffer.length >= options.batchSize) {
                    // 攒满了就走，linger 是给攒不满的情况准备的
                    void flushNow();
                    return;
                }
                // 只有这一批的第一条会起定时器，后来的不顺延
                if (buffer.length === 1) {
                    timer = setTimeout(() => {
                        void flushNow();
                    }, options.lingerMs);
                }
            });
        },
        flush() {
            return flushNow();
        },
        buffered() {
            return buffer.length;
        },
        stats() {
            return { batches: counters.batches, records: counters.records };
        },
    };
}

