// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface RetentionOptions {
//   maxBytes: number;
//   maxAgeMs: number;
// }
//
// export interface CompactionResult {
//   removed: number;
//   kept: number;
// }
//
// export interface LogKeeper {
//   append(key: string, value: string): AppendResult;
//   enforce(): number;
//   compact(): CompactionResult;
//   live(): StoredRecord[];
//   latest(key: string): StoredRecord | null;
//   bytes(): number;
// }
//
// interface Located {
//   record: StoredRecord;
//   segmentId: number;
// }

import { now } from '@lab/env';
export function createLogKeeper(log, storage, options) {
    /** 段 id -> 创建时刻，保留策略按它算年龄 */
    const bornAt = new Map();
    function scan() {
        const found = [];
        for (const segment of storage.segments()) {
            for (let slot = 0; slot < segment.count; slot += 1) {
                const record = storage.readAt(segment.id, slot);
                if (record)
                    found.push({ record, segmentId: segment.id });
            }
        }
        return found;
    }
    /** 每个 key 最后一次出现的 offset。范围是**全部**段。 */
    function latestOffsets(entries) {
        const last = new Map();
        for (const entry of entries)
            last.set(entry.record.key, entry.record.offset);
        return last;
    }
    function activeSegmentId() {
        const segments = storage.segments();
        return segments.length > 0 ? segments[segments.length - 1].id : -1;
    }
    return {
        append(key, value) {
            const result = log.append(key, value);
            if (!bornAt.has(result.segmentId))
                bornAt.set(result.segmentId, now());
            return result;
        },
        enforce() {
            const segments = storage.segments();
            // 活动段还在被写，永远不参与清理
            const sealed = segments.slice(0, segments.length - 1);
            let total = storage.bytes();
            let removed = 0;
            for (const segment of sealed) {
                const age = now() - (bornAt.get(segment.id) || 0);
                const tooOld = age >= options.maxAgeMs;
                const tooBig = total > options.maxBytes;
                // 段按 baseOffset 排序，后面的更新更小，第一个留下的之后都留下
                if (!tooOld && !tooBig)
                    break;
                storage.deleteSegment(segment.id);
                bornAt.delete(segment.id);
                total -= segment.bytes;
                removed += 1;
            }
            return removed;
        },
        compact() {
            const entries = scan();
            const last = latestOffsets(entries);
            const active = activeSegmentId();
            const sealed = entries.filter((entry) => entry.segmentId !== active);
            // 「谁是最新」看全局，「能动谁」只限封存段
            const survivors = sealed.filter((entry) => last.get(entry.record.key) === entry.record.offset);
            const removed = sealed.length - survivors.length;
            if (removed === 0)
                return { removed: 0, kept: entries.length };
            const replaced = Array.from(new Set(sealed.map((entry) => entry.segmentId)));
            if (survivors.length > 0) {
                const target = storage.createSegment(survivors[0].record.offset);
                // 新段继承被它替换掉的那些段里最早的生日：
                // 压缩是整理，不是「让这批数据重新变年轻」，保留时钟不该被它重置
                const ages = replaced.map((segmentId) => bornAt.get(segmentId));
                const known = ages.filter((age) => typeof age === 'number');
                bornAt.set(target, known.length > 0 ? Math.min.apply(null, known) : now());
                // offset 原样搬过去：消费者记住的位置不能被重排
                for (const entry of survivors)
                    storage.append(target, entry.record);
            }
            for (const segmentId of replaced) {
                storage.deleteSegment(segmentId);
                bornAt.delete(segmentId);
            }
            return { removed, kept: entries.length - removed };
        },
        live() {
            const entries = scan();
            const last = latestOffsets(entries);
            return entries
                .filter((entry) => last.get(entry.record.key) === entry.record.offset)
                .map((entry) => entry.record)
                .sort((left, right) => left.offset - right.offset);
        },
        latest(key) {
            const matches = scan().filter((entry) => entry.record.key === key);
            return matches.length > 0 ? matches[matches.length - 1].record : null;
        },
        bytes() {
            return storage.bytes();
        },
    };
}

